  ('CL-2609-007', 0, '{"id":"CL-2609-007","by":"zul","title":"KL supplier visit","purpose":"Feed-mill supply contract follow-up","paidBy":"own","submitted":"2026-10-21","status":"pending","reviewer":"","comment":"","lines":[{"id":"a1","date":"2026-10-20","cat":"Fuel & toll","merchant":"Petron / PLUS","desc":"Return trip Kedah to KL","amount":"162","receipts":[{"name":"petron-0903.jpg","sample":["Petron",0,"receipt"],"isImg":true},{"name":"toll-statement.jpg","sample":["Touch n Go",0,"receipt"],"isImg":true}]},{"id":"a2","date":"2026-10-20","cat":"Meals","merchant":"Kopitiam Sri","desc":"Lunch with mill buyer","amount":"74.2","receipts":[{"name":"kopitiam.jpg","sample":["Kopitiam Sri",0,"receipt"],"isImg":true}]}],"trail":[{"t":"Claim submitted","d":"21 Oct, 08:15","dot":"#097c3e"}]}'::jsonb),
