  ('CL-2609-005', 2, '{"id":"CL-2609-005","by":"e04","title":"Harvest week supplies","purpose":"Crates and crew lunch for harvest week","paidBy":"own","submitted":"2026-10-18","status":"approved","reviewer":"pj","comment":"","lines":[{"id":"c1","date":"2026-10-16","cat":"Farm supplies","merchant":"Agro Supply Sdn Bhd","desc":"Harvest crates x12","amount":"86.4","receipts":[{"name":"agro-supply.jpg","sample":["Agro Supply",0,"receipt"],"isImg":true}]},{"id":"c2","date":"2026-10-17","cat":"Meals","merchant":"Kopitiam Sri","desc":"Crew lunch","amount":"41","receipts":[{"name":"kopitiam.jpg","sample":["Kopitiam Sri",0,"receipt"],"isImg":true}]}],"trail":[{"t":"Claim submitted","d":"18 Oct, 10:02","dot":"#097c3e"},{"t":"Approved by PJ Anandan","d":"18 Oct, 15:40","dot":"#097c3e"}]}'::jsonb),
