insert into public.ops_reports (id, ord, data) values
  ('RP-0011', 0, '{"id":"RP-0011","date":"2026-10-21","by":"e05","title":"Pond B pump replaced","type":"Maintenance","sev":"Medium","status":"Resolved","unit":"Farm — Pond B","body":"Failed pump swapped with the spare. Water flow back to normal after 40 minutes. Old pump kept for parts; impeller is cracked.","images":[{"name":"pump-housing.jpg","sample":["Pump housing",200,"photo"],"isImg":true,"cap":"Pump housing"},{"name":"new-pump-installed.jpg","sample":["New pump installed",170,"photo"],"isImg":true,"cap":"New pump installed"}],"log":[]}'::jsonb),
  ('RP-0010', 1, '{"id":"RP-0010","date":"2026-10-20","by":"e04","title":"Weekly harvest summary","type":"Harvest","sev":"Low","status":"Resolved","unit":"Nursery","body":"Harvest scheduled and completed on time across both ponds. Crates were short on Thursday; borrowed from the packing line.","images":[{"name":"harvest-crates.jpg","sample":["Harvest crates",100,"photo"],"isImg":true,"cap":"Harvest crates"}],"log":[]}'::jsonb),
  ('RP-0009', 2, '{"id":"RP-0009","date":"2026-10-19","by":"e08","title":"BSF feed batch 3 trial results","type":"Daily ops","sev":"Low","status":"In review","unit":"Feed lab","body":"Third batch pelleted at the lower moisture level. Fish uptake looks better than batch 2; need one more week of observation before changing the recipe.","images":[{"name":"feed-batch-3.jpg","sample":["Feed batch 3",40,"photo"],"isImg":true,"cap":"Feed batch 3"},{"name":"pellet-sample.jpg","sample":["Pellet sample",30,"photo"],"isImg":true,"cap":"Pellet sample"},{"name":"fish-response.jpg","sample":["Fish response",190,"photo"],"isImg":true,"cap":"Fish response"}],"log":[]}'::jsonb),
  ('RP-0008', 3, '{"id":"RP-0008","date":"2026-10-18","by":"e05","title":"Algae bloom in Pond A","type":"Incident","sev":"High","status":"Open","unit":"Farm — Pond A","body":"Surface bloom covering roughly a third of the pond since the weekend. Test strip shows high nitrates. Aeration raised; recommend a partial water change and reduced feeding until it clears.","images":[{"name":"pond-a-surface.jpg","sample":["Pond A surface",120,"photo"],"isImg":true,"cap":"Pond A surface"},{"name":"water-test-strip.jpg","sample":["Water test strip",150,"photo"],"isImg":true,"cap":"Water test strip"},{"name":"inlet-pipe.jpg","sample":["Inlet pipe",210,"photo"],"isImg":true,"cap":"Inlet pipe"}],"log":[]}'::jsonb),
  ('RP-0007', 4, '{"id":"RP-0007","date":"2026-10-16","by":"e11","title":"Nursery roof leak","type":"Maintenance","sev":"Medium","status":"Open","unit":"Nursery","body":"Leak above tray rack 3 after heavy rain. Trays moved. Needs sealant and two replacement panels.","images":[{"name":"nursery-roof.jpg","sample":["Nursery roof",20,"photo"],"isImg":true,"cap":"Nursery roof"}],"log":[]}'::jsonb),
  ('RP-0006', 5, '{"id":"RP-0006","date":"2026-10-11","by":"e09","title":"Open day visitor feedback","type":"Customer","sev":"Low","status":"Resolved","unit":"Community","body":"About 60 visitors. Most asked about home-scale kits and bulk pricing. Three schools asked for a tour.","images":[],"log":[]}'::jsonb),
  ('RP-0005', 6, '{"id":"RP-0005","date":"2026-10-06","by":"e07","title":"Delivery cooler failure","type":"Incident","sev":"High","status":"Resolved","unit":"Logistics","body":"Cooler unit stopped mid-route; part of the load was lost. Backup ice used for the rest. Unit serviced and tested.","images":[{"name":"cooler-unit.jpg","sample":["Cooler unit",210,"photo"],"isImg":true,"cap":"Cooler unit"},{"name":"spoiled-stock.jpg","sample":["Spoiled stock",0,"photo"],"isImg":true,"cap":"Spoiled stock"}],"log":[]}'::jsonb),
  ('RP-0004', 7, '{"id":"RP-0004","date":"2026-10-02","by":"e05","title":"Aeration repair overnight","type":"Incident","sev":"Medium","status":"Resolved","unit":"Farm — Pond A","body":"Aerator motor tripped at night. Replaced the capacitor and restored oxygen levels before morning.","images":[{"name":"aerator-motor.jpg","sample":["Aerator motor",220,"photo"],"isImg":true,"cap":"Aerator motor"},{"name":"repair-at-night.jpg","sample":["Repair at night",250,"photo"],"isImg":true,"cap":"Repair at night"}],"log":[]}'::jsonb),
  ('RP-0003', 8, '{"id":"RP-0003","date":"2026-09-25","by":"e04","title":"Monthly safety walk","type":"Safety","sev":"Low","status":"Resolved","unit":"Farm — Pond A","body":"Walkways cleaned and edges marked. Two loose boards replaced. Fire extinguisher dates checked.","images":[{"name":"walkway.jpg","sample":["Walkway",60,"photo"],"isImg":true,"cap":"Walkway"}],"log":[]}'::jsonb),
  ('RP-0002', 9, '{"id":"RP-0002","date":"2026-09-18","by":"e06","title":"Packaging label proofs","type":"Daily ops","sev":"Low","status":"Resolved","unit":"Office","body":"Two label options printed for the feed bag. Option B chosen for readability.","images":[{"name":"label-proof-a.jpg","sample":["Label proof A",300,"photo"],"isImg":true,"cap":"Label proof A"},{"name":"label-proof-b.jpg","sample":["Label proof B",330,"photo"],"isImg":true,"cap":"Label proof B"}],"log":[]}'::jsonb),
  ('RP-0001', 10, '{"id":"RP-0001","date":"2026-09-12","by":"e10","title":"Stock count variance","type":"Daily ops","sev":"Medium","status":"In review","unit":"Office","body":"Month-end count is 12 bags short against the ledger. Checking delivery notes.","images":[],"log":[]}'::jsonb)
